function calculateDistKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

export function queryFallbackVendors(params = {}) {
  const {
    q,
    category,
    area,
    open,
    radius,
    latitude,
    longitude,
    page = 1,
    limit = 18
  } = params;

  let results = [...FALLBACK_VENDORS];

  if (category) {
    const catLower = category.toLowerCase().trim();
    results = results.filter((v) =>
      v.categories?.some(
        (c) =>
          c.slug?.toLowerCase() === catLower ||
          c.id === category ||
          c.name?.toLowerCase() === catLower
      )
    );
  }

  if (area) {
    const areaLower = area.toLowerCase().trim();
    results = results.filter(
      (v) =>
        v.address?.area?.toLowerCase().includes(areaLower) ||
        v.address?.city?.toLowerCase().includes(areaLower) ||
        v.address?.street?.toLowerCase().includes(areaLower) ||
        v.address?.landmark?.toLowerCase().includes(areaLower)
    );
  }

  if (q) {
    const qLower = q.toLowerCase().trim();
    results = results.filter(
      (v) =>
        v.stallName?.toLowerCase().includes(qLower) ||
        v.tagline?.toLowerCase().includes(qLower) ||
        v.description?.toLowerCase().includes(qLower) ||
        v.sampleProducts?.some((p) => p.name?.toLowerCase().includes(qLower)) ||
        v.products?.some((p) => p.name?.toLowerCase().includes(qLower))
    );
  }

  if (open === true || open === "true") {
    results = results.filter((v) => v.availabilityStatus === "open");
  }

  if (latitude && longitude) {
    const lat = parseFloat(latitude);
    const lon = parseFloat(longitude);
    const maxR = radius ? parseFloat(radius) : null;

    results = results
      .map((v) => {
        const coords = v.location?.coordinates;
        if (coords && coords.length === 2) {
          const distKm = calculateDistKm(lat, lon, coords[1], coords[0]);
          return { ...v, distanceKm: parseFloat(distKm.toFixed(2)), distance: Math.round(distKm * 1000) };
        }
        return { ...v, distanceKm: 9999, distance: 9999000 };
      })
      .filter((v) => (maxR ? v.distanceKm <= maxR : true))
      .sort((a, b) => a.distanceKm - b.distanceKm);
  }

  const total = results.length;
  const pageNum = parseInt(page, 10) || 1;
  const limitNum = parseInt(limit, 10) || 18;
  const totalPages = Math.ceil(total / limitNum) || 1;
  const startIndex = (pageNum - 1) * limitNum;
  const paginatedVendors = results.slice(startIndex, startIndex + limitNum);

  return {
    success: true,
    data: {
      vendors: paginatedVendors,
      pagination: {
        total,
        page: pageNum,
        limit: limitNum,
        totalPages
      }
    }
  };
}

export function queryFallbackVendorProfile(id) {
  const vendor = FALLBACK_VENDORS.find((v) => v.id === id || v._id === id);
  if (!vendor) {
    return {
      success: false,
      message: "This vendor stall is currently not publicly available or pending review."
    };
  }

  return {
    success: true,
    data: {
      profile: vendor,
      products: vendor.products || []
    }
  };
}

